pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let residual = bin_residual as f64;

    // Base score: punish large post-residuals (Best-Fit principle)
    // We want to minimize post_residual, so it acts as the primary driver.
    let mut score = post * 1.5;

    // Penalty for creating a bin that is too "tight" to fit future items.
    // If the post-residual is smaller than the next item, we pay a penalty.
    if next_item_size > 0 && post < next_item_size as f64 {
        score += (next_item_size as f64 - post).powf(1.5);
    }

    // Dynamic scaling based on stream progress:
    // Early in the stream, we are aggressive about using existing space to keep open_bins_count low.
    // Late in the stream, we become more selective to avoid "trapping" large items in bad bins.
    let tightness_penalty = (1.0 - progress) * (mean_residual - post).abs();
    score += tightness_penalty;

    // Favor bins that have high occupancy (low residual) to consolidate usage.
    score += (bin_capacity as f64 - residual) * 0.1 * progress;

    // New Bin Logic:
    // If this is a new bin (residual == capacity), we only choose it if it's 
    // significantly better than the current alternatives (e.g., all current bins 
    // would result in very poor fit).
    if bin_residual == bin_capacity {
        // High cost to open a new bin early, lower cost late.
        score += 45.0 * (1.0 - progress * 0.5);

        // If we have many fitting bins, opening a new one is almost always bad.
        score += (fitting_bins_count as f64) * 20.0;
    }

    // Penalize the creation of "orphan" bins (bins with very little space left that
    // likely won't fit future items).
    if post < 10.0 && post > 0.0 {
        score += 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;

    // 1. Non-linear penalty for "Sliver" residuals
    // Small gaps (1-8) are usually wasted. Punish them exponentially.
    if post_residual > 0 && post_residual < 9 {
        score += 65.0 + (9 - post_residual) as f64 * 8.0;
    }

    // 2. Adaptive New Bin Cost
    // Use the mean_residual to gauge if opening a new bin is actually a "better" 
    // alternative to overcrowding an existing one.
    if is_new_bin {
        let progress = step_index as f64 / total_items as f64;
        let density_pressure = (open_bins_count as f64 * 0.5) + (mean_residual * 0.2);
        score += 85.0 + (progress * 40.0) + density_pressure;
    } else {
        // 3. Lookahead Sensitivity
        // If the bin can fit the next item, reward it proportional to how 
        // much space that next item would consume.
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= (next_item_size as f64) * 1.8;
            } else {
                // Penalize if this bin will block the next item
                score += 25.0 + (next_item_size - post_residual) as f64 * 1.5;
            }
        }

        // 4. Fitting Urgency
        // Heavily favor bins that are the only ones capable of holding the item.
        if fitting_bins_count == 1 {
            score -= 75.0;
        }

        // 5. Compaction Bias
        // Encourage keeping residuals low to allow for future large items.
        // Reward bins that maintain high utilization relative to the mean.
        let utilization = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= utilization * 15.0;
    }

    // 6. Global Pressure
    // Penalize the count of open bins as the stream nears completion.
    let stream_completion = step_index as f64 / total_items as f64;
    score += (open_bins_count as f64) * stream_completion * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating "dead space": small residuals (< 10) are almost impossible to fill
    // given the item size range (1..100).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Penalty for opening a new bin if other bins exist.
    // If bin_residual == bin_capacity, this is a new bin candidate.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 40.0;
    }

    // Lookahead pressure: If this bin leaves a residual that cannot accommodate the next item,
    // but another bin might have been better, we penalize it.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Encourage filling bins that are already "half-empty" vs those that are nearly full
    // to keep the number of active bins from exploding.
    if bin_residual < bin_capacity {
        let utilization = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= utilization * 10.0;
    }

    // If this is the only bin that can fit the item, prioritize it heavily to avoid 
    // unnecessary new bin openings.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Dynamic pressure: As the stream progresses, prioritize closing bins to reduce
    // the total count of open bins.
    let progress = step_index as f64 / total_items as f64;
    score += (open_bins_count as f64) * progress * 5.0;

    score
}
